html:
{% set logo = doc.company_logo or '/assets/wafd_one/images/wafd-almadinah-official.png' %}
{% set beneficiary_name = doc.second_party_name or '' %}
{% set beneficiary_id = doc.second_party_cr or '' %}
{% set signatory = doc.authorized_signatory or doc.company_representative or 'نزار بن نذير بن ظفر' %}
<style>
@page { size:A4 portrait; margin:11mm 18mm 10mm 18mm; }
html,body,.print-format{margin:0!important;padding:0!important;background:#fff!important;}
.sheet{direction:rtl;font-family:"Noto Naskh Arabic","Amiri","DejaVu Sans",sans-serif;color:#151515;font-size:12.6px;line-height:1.68;box-sizing:border-box;min-height:276mm;page-break-inside:avoid;}
.header{display:table;width:100%;table-layout:fixed;border-bottom:1.2px solid #b28a38;padding:0 0 4mm;margin:0 0 4.5mm;}
.header-brand,.header-info{display:table-cell;vertical-align:middle;}
.header-brand{width:62%;text-align:right;}
.header-info{width:38%;text-align:left;direction:rtl;color:#4a4a4a;font-family:"DejaVu Sans",sans-serif;font-size:9.8px;line-height:1.65;padding-left:1mm;}
.brand-wrap{display:table;width:100%;table-layout:fixed;}
.brand-logo,.brand-text{display:table-cell;vertical-align:middle;}
.brand-logo{width:30mm;text-align:right;}
.brand-text{text-align:right;padding-right:3mm;}
.logo{width:27mm;height:27mm;object-fit:contain;}
.company-ar{font-size:17px;font-weight:700;line-height:1.35;white-space:nowrap;}
.company-en{font-family:"DejaVu Sans",sans-serif;font-size:9.2px;color:#666;margin-top:1mm;direction:ltr;text-align:right;}
h1{text-align:center;font-size:19px;font-weight:700;text-decoration:underline;text-underline-offset:3px;margin:1.5mm 0 4mm;}
.intro{font-size:12.7px;line-height:1.9;text-align:justify;margin:0 0 3.2mm;}
.details{width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 3.2mm;font-size:11.9px;}
.details td{border:1px solid #a9a9a9;padding:2.2mm 3mm;vertical-align:top;width:50%;min-height:12mm;}
.details b{display:block;font-size:12.1px;margin-bottom:.4mm;}
.value{font-size:12.2px;line-height:1.5;}
.terms{border:1px solid #b5b5b5;padding:2.6mm 3.2mm;margin-top:0;font-size:11.6px;line-height:1.62;page-break-inside:avoid;}
.terms-title{font-size:12.3px;font-weight:700;margin-bottom:.7mm;}
.terms ol{margin:.5mm 5.5mm 0 0;padding:0;}
.terms li{margin:0 0 .35mm;}
.extra{margin-top:1.2mm;}
.approval-section{text-align:center;position:relative;min-height:47mm;margin-top:3.6mm;page-break-inside:avoid;}
.sign-company{font-size:12.2px;font-weight:700;}
.sign-title{font-size:13px;font-weight:700;margin-top:.5mm;}
.approval-canvas{height:38mm;position:relative;margin-top:0;}
.sign-name{position:absolute;top:13mm;left:20%;right:20%;z-index:2;font-size:13px;font-weight:700;white-space:nowrap;}
.signature-img{position:absolute;top:6mm;left:50%;transform:translateX(-50%);width:52mm;height:20mm;object-fit:contain;z-index:3;}
.stamp-img{position:absolute;top:20mm;left:50%;transform:translateX(-50%);width:50mm;height:31mm;object-fit:contain;z-index:1;}
.signature-line{position:absolute;top:18mm;left:35%;right:35%;border-bottom:1px solid #777;}
@media print{.sheet,.header,.details,.terms,.approval-section{break-inside:avoid;page-break-inside:avoid;}}
</style>
<div class="sheet">
  <div class="header">
    <div class="header-brand">
      <div class="brand-wrap">
        <div class="brand-logo"><img class="logo" src="{{ logo }}"></div>
        <div class="brand-text">
          <div class="company-ar">{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</div>
          <div class="company-en">WAFD AL-MADINAH CATERING SERVICES</div>
        </div>
      </div>
    </div>
    <div class="header-info">
      <div>{{ doc.company_address or 'المدينة المنورة — حي الملك فهد' }}</div>
      <div dir="ltr">{{ doc.company_phone or '0500336989' }}</div>
      <div dir="ltr">{{ doc.company_email or 'wafd.almadinah@gmail.com' }}</div>
    </div>
  </div>
  <h1>تعهد والتزام إعاشة</h1>
  <div class="intro">نحن <b>{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</b>، سجل تجاري رقم <b>{{ doc.company_cr or '7051832694' }}</b>، نتعهد بتقديم خدمات الإعاشة للمستفيدين في الفندق الموضح أدناه، وفق البيانات المعتمدة والاشتراطات الصحية والتنظيمية، مع ضمان جودة وسلامة الوجبات أثناء التجهيز والنقل والتسليم.</div>
  <table class="details">
    <tr><td><b>رقم التعهد</b><div class="value">{{ doc.name or '' }}</div></td><td><b>التاريخ</b><div class="value">{{ doc.get_formatted('undertaking_date') if doc.undertaking_date else '' }}</div></td></tr>
    {% if doc.project %}<tr><td><b>المشروع</b><div class="value">{{ doc.project }}</div></td><td><b>الفندق</b><div class="value">{{ doc.hotel or '' }}</div></td></tr>{% else %}<tr><td colspan="2"><b>الفندق</b><div class="value">{{ doc.hotel or '' }}</div></td></tr>{% endif %}
    <tr><td><b>اسم المستفيد</b><div class="value">{{ beneficiary_name }}</div></td><td><b>رقم السجل التجاري أو الهوية للمستفيد</b><div class="value">{{ beneficiary_id }}</div></td></tr>
    <tr><td><b>عدد المستفيدين</b><div class="value">{{ doc.beneficiary_count or 0 }}</div></td><td><b>الجنسية</b><div class="value">{{ doc.nationality or '' }}</div></td></tr>
    <tr><td><b>مدة الخدمة</b><div class="value">{{ doc.get_formatted('start_date') if doc.start_date else '' }} — {{ doc.get_formatted('end_date') if doc.end_date else '' }}</div></td><td><b>الوجبات</b><div class="value">{{ doc.meal_types or '' }}</div></td></tr>
  </table>
  <div class="terms"><div class="terms-title">الشروط والملاحظات:</div><ol><li>تقديم الوجبات المتفق عليها وفق العدد ونوع الوجبة والفترة الموضحة في التعهد.</li><li>الالتزام بمواعيد تجهيز ونقل وتسليم الوجبات دون تأخير.</li><li>الالتزام باشتراطات سلامة الغذاء والنظافة والتعبئة والنقل والحفظ الحراري.</li><li>تسليم الوجبات إلى الفندق المحدد وبالكميات المعتمدة.</li><li>تزويد الفندق بالمستندات النظامية المطلوبة عند الطلب.</li><li>للفندق التحقق من الكميات والحالة الظاهرية عند الاستلام وإثبات أي ملاحظة فوراً.</li><li>لا يُعتد بأي تعديل في العدد أو المواعيد إلا بعد اعتماده من الشركة.</li></ol>{% if doc.additional_terms or doc.service_notes %}<div class="extra"><b>بنود إضافية:</b> {{ doc.additional_terms or doc.service_notes }}</div>{% endif %}</div>
  <div class="approval-section"><div class="sign-company">شركة وفد المدينة لخدمات الإعاشة</div><div class="sign-title">{{ doc.signatory_title or 'المدير العام' }}</div><div class="approval-canvas"><div class="sign-name">{{ signatory }}</div>{% if doc.include_signature and doc.signature_image %}<img class="signature-img" src="{{ doc.signature_image }}">{% else %}<div class="signature-line"></div>{% endif %}{% if doc.include_stamp and doc.company_stamp %}<img class="stamp-img" src="{{ doc.company_stamp }}">{% endif %}</div></div>
</div>
